export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"identifying-mindfulness-of-others-for-each-a-and-b-pair-check-the-more-effective-061f9ec32fa2\",\"title\":\"Identifying Mindfulness of Others For each A and B pair, check the more effective response. \uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3 \\u0003\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9774],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/03-dbt-interpersonal-effectiveness-interpersonal-effectiveness-handout-12a-identifying-mindf-ad606ca9e7.json\",\"sha256\":\"ad606ca9e782cfc6f97e55d4824882eefdc2c00501e3a0f9a7b4d67644d698ad\",\"domain\":\"dbt\",\"bytes\":7498},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/interpersonal-effectiveness-handout-12a-identifying-mindfulness-of-others-for-each-a-and-b-p-2abd1df2d4.json\",\"sha256\":\"2abd1df2d45c13fbf60faf40e501308e29a0a647dbb9724cf0b800806e8df9f3\",\"domain\":\"dbt\",\"bytes\":7329}]},\"data\":{\"pages\":[{\"pdf_page\":168,\"book_page\":\"144\",\"text\":\"144\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nInterpersonal Effectiveness Handout 12a\\nIdentifying Mindfulness of Others\\nFor each A and B pair, check the more effective response.\\n\uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3\\n\\u0003\\n\u0089   1A.\\t Multi-task and expect the other\\nperson to understand.\\n\\u0003\\n\u0089   1B.\\t Give your complete attention to\\nthe person you are with.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   6A.\\t Be open to people\u2019s changing their\\nminds about things, as well as their\\nbeliefs or feelings.\\n\\u0003\\n\u0089   6B.\\t Assume that when people change,\\nthey are not trustworthy.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   2A.\\t Figure that if you already know\\nsomeone, you don\u2019t really have to\\npay such close attention to them\\nany more.\\n\\u0003\\n\u0089   2B.\\t Recognize that closeness is built\\nby attending to and learning more\\nand more about people you care\\nabout.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   7A.\\t Evaluate other people\u2019s behaviors and\\nthoughts, and tell them that they are\\nwrong or that they should be different\\nwhen you feel sure you are right.\\n\\u0003\\n\u0089   7B.\\t If you do not approve of or agree\\nwith what another person is doing\\nor thinking, try to understand how it\\nwould make sense if you knew the\\ncauses.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   3A.\\t \u201cMy feelings are really hurt by\\nwhat you did, and the thought\\nwent through my mind that you\\nhate me. I know that you don\u2019t\\nreally, but did you feel that way at\\nthe time?\u201d\\n\\u0003\\n\u0089   3B.\\t \u201cI know you hate me. There is\\nno other reason for what you did\\nto me. Don\u2019t tell me differently,\\neither.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089   8A.\\t \u201cYou should stop doing that.\u201d\\n\\u0003\\n\u0089   8B.\\t \u201cI wish you would stop doing that.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089   9A.\\t \u201cYou are lazy and have given up.\u201d\\n\\u0003\\n\u0089   9B.\\t \u201cI worry that you have given up.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089 10A.\\t \u201cI don\u2019t think that is correct.\u201d\\n\\u0003\\n\u0089 10B.\\t \u201cHow could you possibly think that?\u201d\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   4A.\\t In social situations, throw yourself\\ninto interactions.\\n\\u0003\\n\u0089   4B.\\t Stay reserved and watch social\\ninteractions so you don\u2019t make\\nmistakes.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089 11A.\\t Stay in control so that relationships\\nturn out the way you want.\\n\\u0003\\n\u0089 11B.\\t Go with the flow much of the time\\nwhen in social interactions with\\ngroups of friends.\\n\uf8f1\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   5A.\\t Find people with your values.\\n\\u0003\\n\u0089   5B.\\t Do little immoral things so as not\\nto be a drag on friendships.\\n\uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3\\n\\u0003\\n\u0089 12A.\\t Hold back in a conversation until you\\nare sure you like the person.\\n\\u0003\\n\u0089 12B.\\t Throw yourself into a conversation\\nuntil you are sure you don\u2019t like it.\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Interpersonal Effectiveness Handout 12a\",\"source_pdf_pages\":[168],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_12a_identifying_mindfulness_of_others_for_each_a_and_b_pair_check_the_more.json\",\"item_number\":\"12a\",\"full_text\":\"Interpersonal Effectiveness Handout 12a\\nIdentifying Mindfulness of Others\\nFor each A and B pair, check the more effective response.\\n\uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3\\n\\u0003\\n\u0089   1A.\\t Multi-task and expect the other\\nperson to understand.\\n\\u0003\\n\u0089   1B.\\t Give your complete attention to\\nthe person you are with.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   6A.\\t Be open to people\u2019s changing their\\nminds about things, as well as their\\nbeliefs or feelings.\\n\\u0003\\n\u0089   6B.\\t Assume that when people change,\\nthey are not trustworthy.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   2A.\\t Figure that if you already know\\nsomeone, you don\u2019t really have to\\npay such close attention to them\\nany more.\\n\\u0003\\n\u0089   2B.\\t Recognize that closeness is built\\nby attending to and learning more\\nand more about people you care\\nabout.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   7A.\\t Evaluate other people\u2019s behaviors and\\nthoughts, and tell them that they are\\nwrong or that they should be different\\nwhen you feel sure you are right.\\n\\u0003\\n\u0089   7B.\\t If you do not approve of or agree\\nwith what another person is doing\\nor thinking, try to understand how it\\nwould make sense if you knew the\\ncauses.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   3A.\\t \u201cMy feelings are really hurt by\\nwhat you did, and the thought\\nwent through my mind that you\\nhate me. I know that you don\u2019t\\nreally, but did you feel that way at\\nthe time?\u201d\\n\\u0003\\n\u0089   3B.\\t \u201cI know you hate me. There is\\nno other reason for what you did\\nto me. Don\u2019t tell me differently,\\neither.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089   8A.\\t \u201cYou should stop doing that.\u201d\\n\\u0003\\n\u0089   8B.\\t \u201cI wish you would stop doing that.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089   9A.\\t \u201cYou are lazy and have given up.\u201d\\n\\u0003\\n\u0089   9B.\\t \u201cI worry that you have given up.\u201d\\n\uf8f1\\n\uf8f2\\n\uf8f3\\n\\u0003\\n\u0089 10A.\\t \u201cI don\u2019t think that is correct.\u201d\\n\\u0003\\n\u0089 10B.\\t \u201cHow could you possibly think that?\u201d\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   4A.\\t In social situations, throw yourself\\ninto interactions.\\n\\u0003\\n\u0089   4B.\\t Stay reserved and watch social\\ninteractions so you don\u2019t make\\nmistakes.\\n\uf8f1\\n\uf8f4\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089 11A.\\t Stay in control so that relationships\\nturn out the way you want.\\n\\u0003\\n\u0089 11B.\\t Go with the flow much of the time\\nwhen in social interactions with\\ngroups of friends.\\n\uf8f1\\n\uf8f4\\n\uf8f2\\n\uf8f4\\n\uf8f3\\n\\u0003\\n\u0089   5A.\\t Find people with your values.\\n\\u0003\\n\u0089   5B.\\t Do little immoral things so as not\\nto be a drag on friendships.\\n\uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3\\n\\u0003\\n\u0089 12A.\\t Hold back in a conversation until you\\nare sure you like the person.\\n\\u0003\\n\u0089 12B.\\t Throw yourself into a conversation\\nuntil you are sure you don\u2019t like it.\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[],\"id\":\"interpersonal_effectiveness_handout_12a\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"144\"],\"title\":\"Identifying Mindfulness of Others For each A and B pair, check the more effective response. \uf8f1 \uf8f4 \uf8f4 \uf8f2 \uf8f4 \uf8f4 \uf8f3 \\u0003\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_12a_identifying_mindfulness_of_others_df5cd7c8.json\",\"module\":\"Interpersonal Effectiveness\",\"keywords\":[\"Identifying\",\"Mindfulness\",\"Others\",\"check\",\"each\",\"effective\",\"more\",\"pair\",\"response\"]}}");
